use novel_storage::{Storage,ProjectIndex,SyncCursor};
use sqlx::Connection;
use serde_json::json;
use sha2::{Digest,Sha256};
async fn fixture()->(tempfile::TempDir,Storage){let d=tempfile::tempdir().unwrap();let s=Storage::open(&d.path().join("chapters.sqlite")).await.unwrap();(d,s)}
async fn heads(s:&Storage,index:&ProjectIndex,cid:&str)->(Option<String>,Option<String>){let c=s.metadata_heads(&index.project.id,cid,"chapter").await.unwrap();let p=s.metadata_heads(&index.project.id,&index.project.id,"project").await.unwrap();assert!(c.revision_ids.len()<=1&&p.revision_ids.len()<=1);(c.revision_ids.first().cloned(),p.revision_ids.first().cloned())}
async fn edit(s:&Storage,index:&ProjectIndex,cid:&str,title:&str,number:i64)->Result<ProjectIndex,String>{let (c,p)=heads(s,index,cid).await;s.edit_chapter(cid,c,p,index.chapters.iter().map(|c|c.id.clone()).collect(),index.chapter_numbering_revision_id.clone(),title,number).await}
#[tokio::test]
async fn chapter_zero_reorders_persists_appends_and_explicitly_returns_to_one(){
 let (d,s)=fixture().await;let p=s.create_project("Novel").await.unwrap();let a=s.create_chapter(&p.id,"أول").await.unwrap();let b=s.create_chapter(&p.id,"中文").await.unwrap();let initial=s.open_project_index(&p.id).await.unwrap();assert_eq!(initial.chapter_number_start,1);assert_eq!(initial.chapter_numbering_revision_id,None);
 let zero=edit(&s,&initial,&b.id,"تمهيد / 序",0).await.unwrap();assert_eq!(zero.chapter_number_start,0);assert_eq!(zero.chapters.iter().map(|c|c.id.as_str()).collect::<Vec<_>>(),vec![b.id.as_str(),a.id.as_str()]);assert_eq!(zero.chapters[0].position,0);assert_eq!(zero.chapters[0].title,"تمهيد / 序");assert!(zero.chapter_numbering_revision_id.is_some());
 let c=s.create_chapter(&p.id,"New chapter").await.unwrap();assert_eq!(c.position,2);assert_eq!(s.open_project(&p.id).await.unwrap().chapter_number_start,0);
 let current=s.open_project_index(&p.id).await.unwrap();let moved=edit(&s,&current,&a.id,"Middle",2).await.unwrap();assert_eq!(moved.chapter_number_start,0);assert_eq!(moved.chapters[2].id,a.id);
 s.close().await;let s=Storage::open(&d.path().join("chapters.sqlite")).await.unwrap();let reopened=s.open_project_index(&p.id).await.unwrap();assert_eq!(reopened.chapter_numbering_revision_id,moved.chapter_numbering_revision_id);assert_eq!(reopened.chapter_number_start,0);
 let one=edit(&s,&reopened,&b.id,"Chapter one",1).await.unwrap();assert_eq!(one.chapter_number_start,1);assert_eq!(one.chapters[0].id,b.id);assert_ne!(one.chapter_numbering_revision_id,reopened.chapter_numbering_revision_id);assert!(one.chapters.iter().all(|c|c.position>=0));
}
#[tokio::test]
async fn chapter_edit_rejects_stale_title_order_numbering_and_invalid_numbers_atomically(){
 let (_d,s)=fixture().await;let p=s.create_project("Novel").await.unwrap();let a=s.create_chapter(&p.id,"A").await.unwrap();let b=s.create_chapter(&p.id,"B").await.unwrap();let initial=s.open_project_index(&p.id).await.unwrap();let (c,ph)=heads(&s,&initial,&a.id).await;let order=initial.chapters.iter().map(|c|c.id.clone()).collect::<Vec<_>>();
 s.rename_chapter(&a.id,"New title").await.unwrap();let before=s.sync_cursor().await.unwrap();assert!(s.edit_chapter(&a.id,c,ph,order,None,"Lost edit",0).await.is_err());assert_eq!(s.sync_cursor().await.unwrap(),before);
 let current=s.open_project_index(&p.id).await.unwrap();let (c,ph)=heads(&s,&current,&a.id).await;s.reorder_chapters(&p.id,vec![b.id.clone(),a.id.clone()]).await.unwrap();assert!(s.edit_chapter(&a.id,c,ph,current.chapters.iter().map(|c|c.id.clone()).collect(),None,"Lost reorder",0).await.is_err());
 let current=s.open_project_index(&p.id).await.unwrap();let (c,ph)=heads(&s,&current,&a.id).await;s.save_project_data(&p.id,"chapterNumbering",json!({"schemaVersion":1,"start":0}),None).await.unwrap();let before=s.open_project_index(&p.id).await.unwrap();assert!(s.edit_chapter(&a.id,c,ph,current.chapters.iter().map(|c|c.id.clone()).collect(),None,"Lost numbering",1).await.is_err());assert_eq!(s.open_project_index(&p.id).await.unwrap(),before);
 for number in [-1,3,i64::MAX]{let marker=s.sync_cursor().await.unwrap();assert!(edit(&s,&before,&a.id,"No mutation",number).await.is_err());assert_eq!(s.sync_cursor().await.unwrap(),marker);assert_eq!(s.open_project_index(&p.id).await.unwrap(),before);}
 for payload in [json!({"schemaVersion":1,"start":2}),json!({"schemaVersion":1,"start":0,"extra":true}),json!({"schemaVersion":2,"start":0}),json!({"schemaVersion":1,"start":0.0}),json!({"schemaVersion":1})]{assert!(s.save_project_data(&p.id,"chapterNumbering",payload,before.chapter_numbering_revision_id.clone()).await.is_err());}
}
#[tokio::test]
async fn chapter_numbering_archive_and_sync_keep_native_offsets_and_validate_imports(){
 let (_d,s)=fixture().await;let p=s.create_project("أرشيف").await.unwrap();let c=s.create_chapter(&p.id,"مقدمة").await.unwrap();let initial=s.open_project_index(&p.id).await.unwrap();let zero=edit(&s,&initial,&c.id,"مقدمة 中文",0).await.unwrap();let archive=s.export_archive(&p.id).await.unwrap();let imported=s.import_archive(&archive).await.unwrap();assert_eq!(imported.chapter_number_start,0);assert_eq!(imported.chapters[0].title,zero.chapters[0].title);assert_ne!(imported.chapter_numbering_revision_id,zero.chapter_numbering_revision_id);
 let (_e,r)=fixture().await;let epoch=s.sync_cursor().await.unwrap().epoch;let local=r.sync_cursor().await.unwrap().epoch;let page=s.pull_revisions(&p.id,SyncCursor{epoch:epoch.clone(),sequence:0},100).await.unwrap();r.ingest_revisions(&p.id,&local,&epoch,s.sync_manifest(&p.id).await.unwrap(),page.revisions.clone()).await.unwrap();assert_eq!(r.open_project_index(&p.id).await.unwrap(),zero);
 let (_f,bad)=fixture().await;let local=bad.sync_cursor().await.unwrap().epoch;let mut invalid=page.revisions;let rev=invalid.iter_mut().find(|r|r.operation=="chapterNumbering").unwrap();rev.payload=json!({"schemaVersion":1,"start":9});rev.checksum=format!("{:x}",Sha256::digest(serde_json::to_vec(&rev.payload).unwrap()));assert!(bad.ingest_revisions(&p.id,&local,&epoch,s.sync_manifest(&p.id).await.unwrap(),invalid).await.is_err());assert!(bad.open_project_index(&p.id).await.is_err());
 // Version-1 portable archives created before numbering fields remain readable.
 let old=s.create_project("Old").await.unwrap();s.create_chapter(&old.id,"First").await.unwrap();let mut archive:serde_json::Value=serde_json::from_str(&s.export_archive(&old.id).await.unwrap()).unwrap();let mut content:serde_json::Value=serde_json::from_str(archive["entries"][0]["content"].as_str().unwrap()).unwrap();let bundle=content["bundle"].as_object_mut().unwrap();for key in ["chapterNumberStart","chapterNumberingRevisionId","chapterNumberingConflicted"]{bundle.remove(key);}let content=serde_json::to_string(&content).unwrap();archive["entries"][0]["size"]=json!(content.len());archive["entries"][0]["sha256"]=json!(format!("{:x}",Sha256::digest(content.as_bytes())));archive["entries"][0]["content"]=json!(content);assert_eq!(s.import_archive(&serde_json::to_string(&archive).unwrap()).await.unwrap().chapter_number_start,1);
}
#[tokio::test]
async fn competing_numbering_heads_block_edits_until_explicit_resolution(){
 let (_d,s)=fixture().await;let p=s.create_project("Novel").await.unwrap();let c=s.create_chapter(&p.id,"First").await.unwrap();let base=s.save_project_data(&p.id,"chapterNumbering",json!({"schemaVersion":1,"start":1}),None).await.unwrap();let (_e,r)=fixture().await;let epoch=s.sync_cursor().await.unwrap().epoch;let local=r.sync_cursor().await.unwrap().epoch;let initial=s.pull_revisions(&p.id,SyncCursor{epoch:epoch.clone(),sequence:0},100).await.unwrap();r.ingest_revisions(&p.id,&local,&epoch,s.sync_manifest(&p.id).await.unwrap(),initial.revisions).await.unwrap();let after=s.sync_cursor().await.unwrap().sequence;
 s.save_project_data(&p.id,"chapterNumbering",json!({"schemaVersion":1,"start":0}),Some(base.revision_id.clone())).await.unwrap();r.save_project_data(&p.id,"chapterNumbering",json!({"schemaVersion":1,"start":1}),Some(base.revision_id)).await.unwrap();let page=s.pull_revisions(&p.id,SyncCursor{epoch:epoch.clone(),sequence:after},100).await.unwrap();r.ingest_revisions(&p.id,&local,&epoch,s.sync_manifest(&p.id).await.unwrap(),page.revisions).await.unwrap();let index=r.open_project_index(&p.id).await.unwrap();assert!(index.chapter_numbering_conflicted);assert!(edit(&r,&index,&c.id,"No silent choice",0).await.is_err());assert!(r.save_project_data(&p.id,"chapterNumbering",json!({"schemaVersion":1,"start":0}),index.chapter_numbering_revision_id).await.is_err());let heads=r.project_data_heads(&p.id,"chapterNumbering").await.unwrap();r.resolve_project_data(&p.id,"chapterNumbering",json!({"schemaVersion":1,"start":0}),heads.revision_ids).await.unwrap();let index=r.open_project_index(&p.id).await.unwrap();assert!(!index.chapter_numbering_conflicted);assert_eq!(edit(&r,&index,&c.id,"Resolved",0).await.unwrap().chapters[0].title,"Resolved");
}
#[tokio::test]
async fn interrupted_numbering_commit_rolls_back_title_order_history_and_markers(){
 let (d,s)=fixture().await;let p=s.create_project("Novel").await.unwrap();let a=s.create_chapter(&p.id,"A").await.unwrap();let b=s.create_chapter(&p.id,"B").await.unwrap();let before=s.open_project_index(&p.id).await.unwrap();let marker=s.sync_cursor().await.unwrap();let old_heads=heads(&s,&before,&b.id).await;
 let mut raw=sqlx::SqliteConnection::connect_with(&sqlx::sqlite::SqliteConnectOptions::new().filename(d.path().join("chapters.sqlite"))).await.unwrap();sqlx::query("CREATE TRIGGER reject_numbering BEFORE INSERT ON revision_envelope WHEN NEW.operation='chapterNumbering' BEGIN SELECT RAISE(ABORT,'Synthetic commit interruption'); END").execute(&mut raw).await.unwrap();
 assert!(edit(&s,&before,&b.id,"Must not leak 中文",0).await.is_err());assert_eq!(s.open_project_index(&p.id).await.unwrap(),before);assert_eq!(s.sync_cursor().await.unwrap(),marker);assert_eq!(heads(&s,&before,&b.id).await,old_heads);assert_eq!(s.open_project_index(&p.id).await.unwrap().chapters[0].id,a.id);assert!(s.load_project_data(&p.id,"chapterNumbering").await.unwrap().is_none());
}
